import java.util.List;
public class Main {
    public static void main(String[] args) {
        int sum = List.of(1, 2, 3, 4).stream()
            .filter(n -> n % 2 == 0)
            .mapToInt(n -> n * n)
            .sum();
        System.out.println(sum);
    }
}

